import { google } from '@ai-sdk/google';
import {
  streamText,
  tool,
  type ModelMessage,
} from 'ai';
import z from 'zod';

let step = 0;
const messageHistory: ModelMessage[] =
  [
    {
      role: 'user',
      content:
        'Write a file to todo.md with the content "Do the dishes"',
    },
  ];

while (step < 5) {
  const result = streamText({
    model: google(
      'gemini-2.0-flash-lite',
    ),
    messages: messageHistory,
    tools: {
      writeFile: tool({
        description:
          'Write a file to the filesystem',
        inputSchema: z.object({
          path: z.string(),
          content: z.string(),
        }),
        execute: async ({
          path,
          content,
        }) => {
          const message = `File written successfully to ${path}!`;
          process.stdout.write(
            'Tool call successful: ' +
              message,
          );
          return message;
        },
      }),
    },
  });

  for await (const chunk of result.textStream) {
    process.stdout.write(chunk);
  }

  const messagesProduced = (
    await result.response
  ).messages;

  messageHistory.push(
    ...messagesProduced,
  );

  const finishReason =
    await result.finishReason;

  if (finishReason === 'stop') {
    break;
  }

  step++;
  process.stdout.write('\n\n');
}

import { google } from '@ai-sdk/google';
import {
  Experimental_Agent,
  stepCountIs,
  tool,
  type ModelMessage,
} from 'ai';
import z from 'zod';

const fsAgent =
  new Experimental_Agent({
    model: google(
      'gemini-2.0-flash-lite',
    ),
    onStepFinish: (step) => {
      process.stdout.write('\n\n');
    },
    tools: {
      writeFile: tool({
        description:
          'Write a file to the filesystem',
        inputSchema: z.object({
          path: z.string(),
          content: z.string(),
        }),
        execute: async ({
          path,
          content,
        }) => {
          const message = `File written successfully to ${path}!`;
          process.stdout.write(
            'Tool call successful: ' +
              message,
          );
          return message;
        },
      }),
    },
    stopWhen: [stepCountIs(5)],
  });

const result =
  await fsAgent.stream({
    messages: [
      {
        role: 'user',
        content:
          'Write a file to todo.md with the content "Do the dishes"',
      },
    ],
  });

for await (const chunk of result.textStream) {
  process.stdout.write(chunk);
}

import { google } from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  type ModelMessage,
  type UIMessage,
  type UIMessageStreamWriter,
  streamText,
  streamObject,
  type LanguageModel,
} from 'ai';
import { z } from 'zod';

declare const model: LanguageModel;

export type MyMessage = UIMessage<
  never,
  {
    suggestions: string[];
  }
>;

declare const modelMessages: ModelMessage[];
declare const writer: UIMessageStreamWriter<MyMessage>;

const stream = createUIMessageStream<MyMessage>({
  execute: async ({ writer }) => {
    // 1. Call streamText, passing in the modelMessages
    // we get from the client
    const streamTextResult = streamText({
      messages: modelMessages,
      model,
    });

    // 2. Send the text/tool calls to the client
    writer.merge(streamTextResult.toUIMessageStream());

    // 3. Consume the stream - this waits until the
    // stream is complete
    await streamTextResult.consumeStream();

    // 4. Call streamObject, using structured outputs
    // to return an array of suggestions
    const followupSuggestionsResult = streamObject({
      model,
      schema: z.object({
        suggestions: z.array(z.string()),
      }),
      messages: [
        // 5. We pass in the existing modelMessages...
        ...modelMessages,
        // 6. ...and the assistant's response
        ...(await streamTextResult.response).messages,
        // 7. ...and a new user message asking for
        // suggestions
        {
          role: 'user',
          content:
            'What question should I ask next? ' +
            'Return an array of suggested questions.',
        },
      ],
    });

    // 8. We send the suggestions to the client (see full example)
  },
});

import { google } from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  generateText,
  streamText,
  type ModelMessage,
  type UIMessage,
  type UIMessageStreamWriter,
} from 'ai';
import { GUARDRAIL_SYSTEM } from './guardrail-prompt.ts';

const checkIsRequestSafe = async (
  modelMessages: ModelMessage[],
) => {
  const guardrailResult = await generateText({
    model: google('gemini-2.0-flash-lite'),
    system: GUARDRAIL_SYSTEM,
    messages: modelMessages,
  });

  // The text will either be '0' or '1'
  const text = guardrailResult.text.trim();

  // If text is exactly '1', the request is safe.

  if (text === '1') {
    return true;
  }

  return false;
};

const streamTextToWriter = (
  writer: UIMessageStreamWriter,
  message: string,
) => {
  const id = crypto.randomUUID();
  writer.write({
    type: 'text-start',
    id,
  });

  writer.write({
    type: 'text-delta',
    id,
    delta: message,
  });

  writer.write({
    type: 'text-end',
    id,
  });
};

const continueStreaming = (
  writer: UIMessageStreamWriter,
  modelMessages: ModelMessage[],
) => {
  const streamTextResult = streamText({
    model: google('gemini-2.0-flash'),
    messages: modelMessages,
  });

  writer.merge(streamTextResult.toUIMessageStream());
};

export const POST = async (
  req: Request,
): Promise<Response> => {
  const modelMessages = convertToModelMessages(
    (await req.json()).messages,
  );

  const stream = createUIMessageStream({
    execute: async ({ writer }) => {
      // 1. Check if the request is safe, using a
      // super-fast LLM request that only returns a
      // single token:
      // - '0' (forbidden)
      // - '1' (allowed)
      const isSafe =
        await checkIsRequestSafe(modelMessages);

      // 2. If the request is not safe, stream the
      // blocked message to the frontend
      if (!isSafe) {
        streamTextToWriter(
          writer,
          'Guardrail blocked the request',
        );

        return;
      }

      // 3. If the request is safe, continue with
      // our normal logic.
      continueStreaming(writer, modelMessages);
    },
  });

  return createUIMessageStreamResponse({
    stream,
  });
};

import { google } from '@ai-sdk/google';
import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  streamObject,
  streamText,
  type ModelMessage,
  type UIMessage,
  type UIMessageStreamWriter,
} from 'ai';
import { z } from 'zod';

// 1. This is the type of our custom UIMessage. This
// gives us type safety on the data-suggestions part
// of the UIMessageStream.
export type MyMessage = UIMessage<
  never,
  {
    suggestions: string[];
  }
>;

const mainModel = google('gemini-2.0-flash');
const suggestionsModel = google('gemini-2.0-flash-lite');

const streamInitialResponse = async (
  modelMessages: ModelMessage[],
  writer: UIMessageStreamWriter<MyMessage>,
) => {
  // 1. Stream the initial response - can be any
  // streamText call with tool calls, etc.
  const streamTextResult = streamText({
    model: mainModel,
    messages: modelMessages,
  });

  // 2. Merge the stream into the UIMessageStream
  writer.merge(streamTextResult.toUIMessageStream());

  // 3. Consume the stream - this waits until the
  // stream is complete
  await streamTextResult.consumeStream();

  // 4. Return the messages from the response, to
  // be used in the followup suggestions
  return (await streamTextResult.response).messages;
};

const generateFollowupSuggestions = (
  modelMessages: ModelMessage[],
) =>
  // 1. Call streamObject, which allows us to stream
  // structured outputs to the frontend
  streamObject({
    model: suggestionsModel,
    // 2. Pass in the full message history
    messages: [
      ...modelMessages,
      // 3. And append a request for followup suggestions
      {
        role: 'user',
        content:
          'What question should I ask next? Return an array of suggested questions.',
      },
    ],
    // 4. These suggestions are made type-safe by
    // this Zod schema
    schema: z.object({
      suggestions: z.array(z.string()),
    }),
  });

const streamFollowupSuggestionsToFrontend = async (
  // 1. This receives the streamObject result from
  // generateFollowupSuggestions
  followupSuggestionsResult: ReturnType<
    typeof generateFollowupSuggestions
  >,
  writer: UIMessageStreamWriter<MyMessage>,
) => {
  // 2. Create a data part ID for the suggestions - this
  // ensures that only ONE data-suggestions part will
  // be visible in the frontend
  const dataPartId = crypto.randomUUID();

  // 3. Read the suggestions from the stream
  for await (const chunk of followupSuggestionsResult.partialObjectStream) {
    // 4. Write the suggestions to the UIMessageStream
    writer.write({
      id: dataPartId,
      type: 'data-suggestions',
      data:
        chunk.suggestions?.filter(
          // 5. Because of some AI SDK type weirdness,
          // we need to filter out undefined suggestions
          (suggestion) => suggestion !== undefined,
        ) ?? [],
    });
  }
};

export const POST = async (
  req: Request,
): Promise<Response> => {
  const body = await req.json();

  const modelMessages = convertToModelMessages(
    body.messages,
  );

  // 1. Create a UIMessageStream, which can handle multiple
  // streams being composed into it
  const stream = createUIMessageStream<MyMessage>({
    execute: async ({ writer }) => {
      // 2. Stream the initial response (could be any streamText
      // call with tool calls, etc.)
      const messagesFromResponse =
        await streamInitialResponse(modelMessages, writer);

      // 3. Generate the followup suggestions, passing in the
      // full message history
      const followupSuggestions =
        generateFollowupSuggestions([
          ...modelMessages,
          ...messagesFromResponse,
        ]);

      // 4. Stream the followup suggestions to the frontend
      await streamFollowupSuggestionsToFrontend(
        followupSuggestions,
        writer,
      );
    },
  });

  return createUIMessageStreamResponse({
    stream,
  });
};

Here's a pattern for validating incoming requests to your LLM application to make sure that they're safe. We're in TypeScript and we're using the AI SDK.

## The Fast Model Approach

The juiciest nugget is inside the `checkIsRequestSafe` function. The idea here is that we use a very, very fast model, in this case Gemini 2.0 Flash Lite.

```ts
const checkIsRequestSafe = async (
  modelMessages: ModelMessage[],
) => {
  const guardrailResult = await generateText({
    model: google('gemini-2.0-flash-lite'),
    system: GUARDRAIL_SYSTEM,
    messages: modelMessages,
  });

  // The text will either be '0' or '1'
  const text = guardrailResult.text.trim();

  // If text is exactly '1', the request is safe.

  if (text === '1') {
    return true;
  }

  return false;
};
```

We pass it all of the messages in the conversation history so far, and we get it to run extremely quickly by only returning a single token. This is done inside the guardrail system prompt.

```ts
## Response Format

Respond with just the number:

1

or

0
```

Because it's just returning a single token, this will run very, very quickly. And it means that we can do some imperative logic here, saying if the text is exactly `1`, then the request is safe, so we can return `true`.

## Alternative Approaches

Lots of folks pointed out in the comments it doesn't have to be `0` or `1`, you can use a single word. Since for the LLM it's actually generating tokens under the hood, numbers.

So it would take exactly the same amount of time for it to generate the word "safe" as it would to generate the word "one", but this is the implementation I landed on and it works pretty well.

## Streaming Text to the Frontend

Next we should look at this `streamTextToWriter` function. It's useful any time that you need to stream any arbitrary text to the front end.

```ts
const streamTextToWriter = (
  writer: UIMessageStreamWriter,
  message: string,
) => {
  const id = crypto.randomUUID();
  writer.write({
    type: 'text-start',
    id,
  });

  writer.write({
    type: 'text-delta',
    id,
    delta: message,
  });

  writer.write({
    type: 'text-end',
    id,
  });
};
```

Here we're streaming three parts, `textStart`, `textDelta` and `textEnd`, all with the same `id`. To be honest it's pretty verbose and I wish the AI SDK would make this a little bit easier, since all we need to do is really stream this message to the frontend.

## Continuing with Normal Streaming

Finally then we continue streaming with the writer and with the model messages.

```ts
const continueStreaming = (
  writer: UIMessageStreamWriter,
  modelMessages: ModelMessage[],
) => {
  const streamTextResult = streamText({
    model: google('gemini-2.0-flash'),
    messages: modelMessages,
  });

  writer.merge(streamTextResult.toUIMessageStream());
};
```

This is a normal `streamText` call where we're merging it into the writer.

## Applications of Fast LLM Responses

This logic of a very, very fast LLM response for the rest of your logic is something that we can map into lots of different use cases:

- We could use this as a router to route certain requests through a smarter LLM
- Or route simple ones to a stupid fast LLM, which would be an amazingly cost-saving measure

There's a lot of people out there, maybe you included, who still don't know what tokens are. Tokens are the currency of LLMs - you don't get billed in characters, you get billed in tokens.

So you need to know what a token is because you're being charged for them. Let's explain it in under two minutes.

## How LLMs Process Text

LLMs don't actually work with text, they work with numbers. Every piece of text that you send to an LLM gets turned into tokens, which are just an array of numbers.

I'm using here the tokenizer that's used for GPT-4o, or rather a JavaScript implementation of it called `js-tiktoken`:

```ts
import { Tiktoken } from 'js-tiktoken/lite';
import o200k_base from 'js-tiktoken/ranks/o200k_base';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const tokenizer = new Tiktoken(
  // NOTE: o200k_base is the tokenizer for GPT-4o
  o200k_base,
);
```

## Tokens vs Characters

I have a rather large piece of text here in `input.md`. I'm reading that file into memory and then I'm turning it into tokens using the `textToTokens` function:

```ts
const textToTokens = (text: string) => {
  return tokenizer.encode(text);
};

const input = readFileSync(
  path.join(import.meta.dirname, 'input.md'),
  'utf-8',
);

const output = textToTokens(input);

console.log('Content length in characters:', input.length);
console.log(`Number of tokens:`, output.length);
console.dir(output, { depth: null, maxArrayLength: 20 });
```

When I run this, we can see that the content length in characters, the number of letters it is, is nearly 2,300, but the number of tokens is only 484.

```
Content length in characters: 2294
Number of tokens: 484
```

That's because tokens are _chunks_ of text. They're not individual characters.

## What LLMs Actually Process

So that's what the LLM is actually reading - the tokens, not the text. You might think to yourself that LLMs are trained on text, but really they're trained on text that's been turned into tokens.

And what does an LLM output? Well, it outputs more tokens. It outputs numbers, not text, and then that tokenizer takes those tokens and turns them into text that we can read.

## Converting Tokens Back to Text

For instance, we can just pick out any random numbers here and turn them into text:

```ts
const tokensToText = (tokens: number[]) => {
  return tokenizer.decode(tokens);
};

const tokens = [13984];
const decoded = tokensToText(tokens);
console.log(decoded);
```

I found the magic token `13984` turns into `VC`. Funny.

## Why Tokens Matter

Tokens are really how LLMs think. They think in numbers, not text, and they are the currency of LLMs.

The more text you give them, that's going to be turned into more tokens, which you will then be billed for.

| Text Processing | What's Actually Happening                     |
| --------------- | --------------------------------------------- |
| You send text   | Text is converted to tokens (numbers)         |
| LLM processes   | LLM works with tokens, not text               |
| LLM responds    | LLM outputs tokens that are converted to text |
| You get billed  | Based on number of tokens, not characters     |

Most people think that LLMs can really only produce text. And they don't think about the second thing they're really good at, which is producing structured outputs.

I have here an invoice that I'm going to pass to the LLM to extract out the information. I want to extract it out because it's in a PDF - I can't put a PDF in a database to query the raw information.

## Setting Up the Invoice Extraction

I'm going to take that PDF and read it into memory here, and then we're going to send it to Claude 3.7 Sonnet. I'm using the AI SDK here and TypeScript.

```ts
import { anthropic } from '@ai-sdk/anthropic';
import { generateObject, streamText } from 'ai';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import z from 'zod';

const invoice = readFileSync(
  path.join(import.meta.dirname, 'invoice.pdf'),
);

const result = await generateObject({
  schema: z.object({
    items: z.array(
      z.object({
        name: z.string(),
        quantity: z.number(),
        price: z.number(),
      }),
    ),
    total: z.number(),
    currency: z.string(),
  }),
  model: anthropic('claude-3-7-sonnet-20250219'),
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'text',
          text: 'Give me a summary of this invoice.',
        },
        {
          type: 'file',
          data: invoice,
          mediaType: 'application/pdf',
        },
      ],
    },
  ],
});
```

## From Text to Structured Data

Now I'm using `streamText` here, which means I'm just going to get a text output. And that's fine, we end up with a nice little summary coming back for us.

Instead I'm going to replace this `streamText` call with a `generateObject` call. I'm then going to pass it a schema of all of the things I want to get back.

```ts
const result = await generateObject({
  schema: z.object({
    items: z.array(
      z.object({
        name: z.string(),
        quantity: z.number(),
        price: z.number(),
      }),
    ),
    total: z.number(),
    currency: z.string(),
  }),
  model: anthropic('claude-3-7-sonnet-20250219'),
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'text',
          text: 'Give me a summary of this invoice.',
        },
        {
          type: 'file',
          data: invoice,
          mediaType: 'application/pdf',
        },
      ],
    },
  ],
});
```

## Defining the Schema with Zod

I'm using Zod here to declare the schema. In this case, it's an array of objects where we have name, quantity, and price. I want to see that I bought three watermelons, two mangoes, and one peach.

```ts
schema: z.object({
  items: z.array(
    z.object({
      name: z.string(),
      quantity: z.number(),
      price: z.number(),
    }),
  ),
  total: z.number(),
  currency: z.string(),
}),
```

And when I run this now, I can see all of the items in an actual structured object that I can then plug directly into a database or just display in a table in the UI.

```ts
console.dir(result.object, { depth: null });
```

## A Recent Innovation

All of this stuff, of course, is relatively new. This is OpenAI announcing this August 6th last year. And it's essentially a feature of their API.

When you enable structured outputs, you're more likely to get a response that matches the schema that you send. So it's not a feature that's innate to LLMs. It's something that the model providers provide as a service on top of their models.

## Summary

Structured outputs allow you to get objects out of LLMs, not just text, and we used a PDF as the input here, but you can use any text or image.

| Traditional LLM Output | Structured Output     |
| ---------------------- | --------------------- |
| Raw text               | JSON objects          |
| Requires parsing       | Ready for database/UI |
| Inconsistent format    | Schema-validated      |

When passing data to an LLM, you've got to be careful about how that data is formatted, otherwise you might waste a ton of tokens. Let's look at an example:

## The Problem: Inefficient JSON Format

Here, we have a bunch of video transcription data in a JSON file. We want to send it to an LLM to summarize a conversation and answer questions about it.

```json
[
  {
    "text": "Welcome everyone to today's presentation on artificial intelligence.",
    "start": 0.5,
    "end": 4.2,
    "speaker": "Speaker_1",
    "confidence": 0.92
  }
  // ...
]
```

It's tempting to take this JSON and pass it directly to the LLM. But doing that would be a huge waste of tokens.

## Measuring Token Usage

Let's see how many tokens this JSON file uses. We'll use the same tokenizer that GPT-4o uses - `js-tiktoken`:

```javascript
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { Tiktoken } from 'js-tiktoken/lite';
import o200k_base from 'js-tiktoken/ranks/o200k_base';

const tokenizer = new Tiktoken(
  o200k_base,
);

const jsonData = readFileSync(
  path.join(
    import.meta.dirname,
    'data.json',
  ),
  'utf-8',
);

const jsonTokens =
  tokenizer.encode(jsonData);

console.log(jsonTokens.length);
```

When we run this code, we can see that this JSON file gets turned into ~2,350 tokens. If you want to know why this specific number, check out [my video on tokens](https://www.youtube.com/watch?v=nKSk_TiR8YA).

## The Solution: Custom Format

We can cut the token count nearly in half by using a custom format. Here's how:

1. Parse the JSON data
2. Map over each item in the array
3. Format each item as a single line with values separated by pipe characters
4. Join the lines with newlines
5. Add a header line for clarity

Here's the code to do this:

```ts
const formattedData = JSON.parse(
  jsonData,
)
  .map(
    (item: {
      text: string;
      start: number;
      end: number;
      speaker: string;
      confidence: number;
    }) => {
      return `${item.speaker}|${item.confidence}|${item.text}|${item.start}|${item.end}`;
    },
  )
  .join('\n');

const headerLine =
  'speaker|confidence|text|start|end';

const formattedTokens =
  tokenizer.encode(
    headerLine +
      '\n' +
      formattedData,
  );

console.log(
  formattedTokens.length,
);
```

## Results Comparison

Let's compare the token counts:

| Format | Token Count  |
| ------ | ------------ |
| JSON   | 2,350 tokens |
| Custom | 1,200 tokens |

As you can see, we've cut the token count nearly in half, just by using a custom format.

## Why This Works

The custom format is more efficient because:

- It eliminates redundant field names (like "text", "speaker", etc.)
- It removes unnecessary JSON syntax (curly braces, quotation marks)
- It uses compact delimiters (pipe characters)

Over a much larger data set, this approach will be even more impactful.

## The Takeaways

I strongly recommend that whenever you're passing data to an LLM, use your own custom format. It's going to save you both time and money.

This technique works especially well for:

- Transcripts
- Log data
- Tabular data
- Any structured information

By being thoughtful about your data formatting, you can dramatically reduce token usage and the associated costs when working with large language models.

